# coding: utf-8
from pathlib import Path
import json,hashlib,sys
p=Path(__file__).resolve().parent
read=lambda n:json.loads((p/n).read_text())
first,filled,jsc,pressure,churn,live=[read(n) for n in ['native-first-load-results.json','native-filled-first-load-results.json','artist-jsc-results.json','native-pressure-results.json','mixed-native-churn-results.json','live-source-results.json']]
tests=(p/'tests.log').read_text();assert '# tests 2097' in tests and '# pass 2097' in tests and '# fail 0' in tests
assert len(first['runs'])==204 and len(filled['runs'])==204 and len(jsc['runs'])==48
assert sum(x['lyricResponses'] for x in churn['results'])==4800
assert all(x['warmHTTP']==0 and x['activeHTTP']==0 and x['maxActiveHTTP']==1 for x in churn['results'])
assert all(x['peakHTTP']==1 and x['peakLiveInvocations']==2 and x['admissionTimers']==0 for x in pressure['comparisons'])
assert live['lines']==42 and live['synced'] and live['warmHTTP']==0 and live['done']==1 and live['active']==0
snap=read('bench-runtime-sha256.json')
assert {str(f.relative_to(p/'runtime')):hashlib.sha256(f.read_bytes()).hexdigest() for f in (p/'runtime').rglob('*') if f.is_file()}==snap['candidate']
out=['# VerseLyrics 3.1.9 validation and measurements','','Repairing source matching for explicit bilingual artist labels. Desktop compiled-host mocks and macOS JavaScriptCore are not the Loon/iPhone VPN process. All regressions and extra work of newly working paths are retained below. Network-free tables exclude service latency.','','## Confirmed repair','','- 2,097 automated tests pass, including 107 added cases (60 compiled native client/format cases). All 1,990 prior cases remain; current negative-cache fixtures use revision 8 and older test import paths now read the canonical .lpx entry in a clean output directory.','- Real public Spotify metadata identifies KimYeji — Burn It Down, track 5gjHrjV4IhqPqoDHQUAriQ, at 213600 ms. The QQ search returns the same title, 김예지 (Kim Yeji), and 213 seconds. The exact same public replies yield no lyric document in 3.1.8 and 42 timed lines in 3.1.9.','- Matching is generic: no production track-ID or artist override, new provider, external name-translation query, embedded song lyrics or fabricated timeline. Full name alternatives must be explicitly present in one bilingual label. Collaborators, title, duration, album/version and relaxed-album uniqueness remain checked.','- Old negative ordinary/timed source records are invalidated by source revision 8; successful lyrics and translations remain reusable. No global purge, new timer, concurrent HTTP request, storage key or capacity increase.','','## Actual public source requests','','The compiled Loon host mock starts with empty storage and simulates an official HTTP 404. It really fetches public Spotify embed metadata and queries the existing sources. LRCLIB times out in its existing 1.6-second first-source allowance; QQ then returns the matching catalog entry and LRC. Four serialized transports including metadata, 42 timed lines, one completion, no pending transport, then zero HTTP on warm reopen with byte-identical output. The entire check including warm reopen took %.3f seconds. Translation was disabled for this real-song source probe; self-written bilingual fixtures cover source fallback plus translation in all five compiled clients. No phone request or protected Spotify lyric response was captured. See live-source-results.json and target-track-reproduction.json.'%(live['flowMs']/1000),'','## First-load comparisons','','Each table uses 204 fresh Node processes (six alternating trials per version/scenario), one newly compiled Loon script/VM per process and 32 MiB old-space. Output hashes and request counts match on all unchanged ordinary cases. Populated runs start with 48000–60000 unrelated cache characters. Samples include harness/compiler/code-cache overhead and do not capture every transient/native allocation. Baseline is 3.1.8; candidate is 3.1.9.']
for name,d in [('Empty cache',first),('Populated cache',filled)]:
 out+=['','### '+name,'','| Scenario | Baseline ms | Candidate ms | Time change | Sampled heap change (bytes) |','| --- | ---: | ---: | ---: | ---: |']
 for r in d['comparisons']:
  a,b=r['baseline'],r['candidate'];out.append('| '+r['scenario']+' | %.3f | %.3f | %+.3f%% | %+d |'%(a['medianMs'],b['medianMs'],(b['medianMs']/a['medianMs']-1)*100,b['sampledMaxHeapBytes']-a['sampledMaxHeapBytes']))
out+=['','## macOS JavaScriptCore','','48 fresh processes, six alternating trials per version/case. Same self-written JSON lyrics, source translations, exact/bilingual catalog fixtures and zero-latency native HTTP mocks. Bilingual cold baseline cases deliberately miss lyrics: the new working lookup does more work and is not a memory reduction. Footprint and RSS include harness, JIT and process overhead.','','| Case | Version | Processing ms | Sampled peak footprint bytes | Max RSS bytes | HTTP | Lyric rows |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
for r in jsc['summary']:out.append('| %s | %s | %.3f | %.0f | %.0f | %d | %d |'%(r['case'],r['version'],r['milliseconds'],r['sampledPeakFootprint'],r['maxRSS'],r['calls'],r['rows']))
out+=['','## Repeated responses and limits','','- Twenty native client/format/cache-mode playlists complete 4,800 lyric responses. Warm HTTP is 0; active HTTP peaks at 1 and is 0 after completion. Standard and compact capacities are checked on each response.','- Sixteen arrival-pressure processes retain at most 2 live mock invocations, 1 HTTP request and 0 admission timers. Native synchronous storage remains advisory rather than an atomic device-wide lock.','- The extra source identity code adds 1,107 bytes to the compiled Loon lyric runtime (91,869 to 92,976 bytes); the 30,643-byte Loon entry script is unchanged in size. It adds no provider lookup or runtime dependency. See runtime-manifest.json for exact measured bytes.','- Cold ordinary Node timings increase by 0.021–0.734 ms in this sample; sampled heap changes range from -222024 to +22632 bytes. Populated cases show 0.039–0.627 ms timing increases and -6408 to +10536 byte heap changes. These are samples, not guaranteed regressions/improvements on a phone.','- For the 48-row JSC exact-name case, sampled footprint rises by 98304 bytes; the restored bilingual path necessarily performs the lyric fetch that the failed baseline skipped. This release claims corrected coverage within existing bounds, not a universal speed/RAM reduction.','- Limits remain: 256 KiB lyric body; 128 KiB entry body; 96 KiB service reply; 600 rows; 12 source requests and 256 KiB cumulative source bytes; 64 original rows/translation batch, 6800 URL characters and 2.5-second translation window. Cache: standard 128 entries/64000 characters; compact 64/32000; existing per-entry limits.','- Translation, mixed Chinese/English, no Chinese script-only conversion, vocal-language handling, static replacement switch, original colors/timing and all six sources remain tested.','- No actual iPhone VPN or UI acceptance was performed. JavaScript checks cannot bound native HTTP/decompression buffers or promise the OS will never terminate a VPN extension.','','## Reproduction','','Use the exact pnpm lockfile, node build.mjs, python3 package.py RUNTIME_COMMIT 2097, node --test --test-reporter=tap *.test.mjs core/test/*.test.mjs and ruby validate-egern.rb. Run python3 run-measurements-319.py NODE BASELINE_318_SOURCE and python3 summarize-319.py BASELINE_318_SOURCE. The immutable baseline source/runtime commit is dce3a071f048bd3a58711dc0440aa10c8c0b5401, source prefix Surge/Development/VerseLyrics318. Source/runtime hashes are frozen before and after each measurement step.','','For a fresh public lookup run node live-source-check.mjs. To reproduce the two-core comparison, python3 fetch-target-fixtures.py returns a local temporary directory; pass it to node reproduce-bilingual-source.mjs BASELINE_318_SOURCE FIXTURE_DIRECTORY. Provider results and network latency may change. Raw song lyrics and public embed session data are not included in this archive.','']
# Derive runtime size from the frozen artifacts rather than handwritten byte counts.
baselineRoot=Path(sys.argv[1]) if len(sys.argv)>1 else p.parent/'baseline'
baselineBytes=len((baselineRoot/'runtime/Loon/script/SpotifyLyrics.js').read_bytes());candidateBytes=len((p/'runtime/Loon/script/SpotifyLyrics.js').read_bytes())
out=[s.replace('1,107 bytes','%s bytes'%format(candidateBytes-baselineBytes,',')).replace('92,976 bytes','%s bytes'%format(candidateBytes,',')) for s in out]
(p/'MEASUREMENTS.md').write_text('\n'.join(out))
report={'version':'3.1.9','baseline':'3.1.8','baselineSourceCommit':'dce3a071f048bd3a58711dc0440aa10c8c0b5401','tests':2097,'addedTests':107,'newNativeClientFormatTests':60,'nodeFreshProcesses':408,'jscFreshProcesses':48,'mixedNativeResponses':4800,'warmHTTP':0,'peakMockHTTP':1,'arrivalPressureProcesses':16,'mockAdmissionTimers':0,'publicTargetTimedLines':42,'publicSourceHTTPIncludingMetadata':4,'protectedSpotifyLyricResponseCaptured':False,'phoneUIAndVPNAcceptance':False,'runtimeHashes':'bench-runtime-sha256.json','fullMeasurements':'MEASUREMENTS.md'}
(p/'validation-summary.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
